// Retire des textes GitHub du dépôt (issues, PR, commentaires, avis de revue) les pieds de
// page d'attribution qu'ajoute l'environnement des agents (CLAUDE.md, « Règles Git » : tout le
// projet est au nom de Mathis).
//
//   node .github/scripts/nettoyer-mentions.mjs evenement   texte de l'événement courant
//   node .github/scripts/nettoyer-mentions.mjs arriere [budget] [--avis]
//                                                         textes déjà publiés, au plus
//                                                         `budget` modifications (300)
//
// Variables : GITHUB_TOKEN, GITHUB_REPOSITORY, GITHUB_EVENT_PATH (fournies par Actions).
// Les motifs sont écrits sans le nom de l'outil en clair (`cl[a]ude`), pour que ce fichier
// n'en contienne aucune mention.
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const TOOL = 'cl[a]ude';
const COMPANY = 'anthr[o]pic';

/** Lignes retirées entièrement. */
const LINE_PATTERNS = [
  // « _Generated by [Outil](https://…)_ », « 🤖 Generated with [Outil](…) ».
  new RegExp(`^\\s*(?:\\S+\\s+)?_?generated (?:with|by) \\[[^\\]]*\\]\\([^)]*\\)_?\\.?\\s*$`, 'i'),
  // Lien de session seul sur sa ligne.
  new RegExp(`^\\s*<?https://${TOOL}\\.(?:ai|com)/code[^\\s>]*>?\\s*$`, 'i'),
  // Lignes d'attribution recopiées dans un texte.
  new RegExp(`^\\s*(?:co-authored-by|${TOOL}-session):.*(?:${TOOL}|${COMPANY}).*$`, 'i'),
];

/** Remplacements dans le texte courant (mentions dans une phrase). */
const INLINE_REPLACEMENTS = [
  [new RegExp(`Co-authored-by: ${TOOL}(?: <[^>]*>)?`, 'gi'), 'Co-authored-by'],
  [new RegExp(`« ${TOOL} »`, 'gi'), '« externe »'],
];

/**
 * Texte sans pied d'attribution : lignes de `LINE_PATTERNS` retirées, puis le séparateur
 * `---` et les lignes vides laissés orphelins en fin de texte. Le reste est inchangé, à
 * l'octet près (`CLAUDE.md`, nom de fichier, n'est pas une mention).
 */
export function cleanText(text) {
  if (typeof text !== 'string' || text.length === 0) return text;
  const all = text.split('\n');
  const lines = all.filter((line) => !LINE_PATTERNS.some((p) => p.test(line)));
  const removed = lines.length < all.length;
  if (removed) {
    while (lines.length > 0 && /^\s*(?:-{3,}|\*{3,}|_{3,})?\s*$/.test(lines.at(-1))) lines.pop();
  }
  let cleaned = lines.join('\n');
  for (const [pattern, replacement] of INLINE_REPLACEMENTS) {
    cleaned = cleaned.replace(pattern, replacement);
  }
  return removed || cleaned !== text ? cleaned : text;
}

/** Vrai si le texte contient encore une mention (hors nom de fichier `CLAUDE.md`). */
export function hasMention(text) {
  if (typeof text !== 'string') return false;
  return new RegExp(`\\b(?:${TOOL}(?!\\.md)|${COMPANY})\\b`, 'i').test(text);
}

class GitHub {
  constructor(token, repository) {
    this.token = token;
    this.base = `https://api.github.com/repos/${repository}`;
    this.edits = 0;
  }

  async request(method, path, body) {
    for (let attempt = 1; ; attempt++) {
      const response = await fetch(path.startsWith('http') ? path : `${this.base}${path}`, {
        method,
        headers: {
          authorization: `Bearer ${this.token}`,
          accept: 'application/vnd.github+json',
          'x-github-api-version': '2022-11-28',
          ...(body ? { 'content-type': 'application/json' } : {}),
        },
        body: body ? JSON.stringify(body) : undefined,
      });
      if (response.ok) return response.status === 204 ? null : response.json();
      const limited = response.status === 403 || response.status === 429;
      if (limited && attempt < 4) {
        const wait = Number(response.headers.get('retry-after') ?? 60);
        console.log(`Limite de l'API : nouvel essai dans ${wait} s.`);
        await new Promise((done) => setTimeout(done, wait * 1000));
        continue;
      }
      throw new Error(`${method} ${path} : ${response.status} ${await response.text()}`);
    }
  }

  async *pages(path) {
    for (let page = 1; ; page++) {
      const separator = path.includes('?') ? '&' : '?';
      const items = await this.request('GET', `${path}${separator}per_page=100&page=${page}`);
      yield* items;
      if (items.length < 100) return;
    }
  }

  /** Corrige un texte si besoin ; renvoie vrai si une modification a été faite. */
  async fix(method, path, body, label) {
    const cleaned = cleanText(body);
    if (cleaned === body) return false;
    await this.request(method, path, { body: cleaned });
    this.edits++;
    console.log(`Corrigé : ${label}`);
    // Les créations de contenu ont une limite secondaire : une modification par seconde.
    await new Promise((done) => setTimeout(done, 1000));
    return true;
  }
}

async function cleanEvent(github, event) {
  const { issue, comment, pull_request: pull, review } = event;
  if (comment) {
    const kind = comment.pull_request_review_id ? 'pulls/comments' : 'issues/comments';
    await github.fix('PATCH', `/${kind}/${comment.id}`, comment.body, `commentaire ${comment.id}`);
  } else if (review && pull) {
    await github.fix(
      'PUT',
      `/pulls/${pull.number}/reviews/${review.id}`,
      review.body,
      `avis ${review.id} de #${pull.number}`,
    );
  } else if (issue ?? pull) {
    const item = issue ?? pull;
    await github.fix('PATCH', `/issues/${item.number}`, item.body, `#${item.number}`);
  }
}

async function cleanBacklog(github, budget, withReviews) {
  const remaining = () => budget - github.edits;
  for await (const item of github.pages('/issues?state=all&sort=created&direction=desc')) {
    if (remaining() <= 0) break;
    await github.fix('PATCH', `/issues/${item.number}`, item.body, `#${item.number}`);
  }
  for await (const comment of github.pages('/issues/comments?sort=created&direction=desc')) {
    if (remaining() <= 0) break;
    await github.fix('PATCH', `/issues/comments/${comment.id}`, comment.body, `commentaire ${comment.id}`);
  }
  for await (const comment of github.pages('/pulls/comments?sort=created&direction=desc')) {
    if (remaining() <= 0) break;
    await github.fix('PATCH', `/pulls/comments/${comment.id}`, comment.body, `commentaire ${comment.id}`);
  }
  if (!withReviews) return;
  for await (const pull of github.pages('/pulls?state=all&sort=created&direction=desc')) {
    if (remaining() <= 0) break;
    for await (const review of github.pages(`/pulls/${pull.number}/reviews`)) {
      if (remaining() <= 0) break;
      await github.fix(
        'PUT',
        `/pulls/${pull.number}/reviews/${review.id}`,
        review.body,
        `avis ${review.id} de #${pull.number}`,
      );
    }
  }
}

async function main() {
  const [mode = 'evenement', budgetArg] = process.argv.slice(2);
  const { GITHUB_TOKEN, GITHUB_REPOSITORY, GITHUB_EVENT_PATH } = process.env;
  if (!GITHUB_TOKEN || !GITHUB_REPOSITORY) {
    throw new Error('GITHUB_TOKEN et GITHUB_REPOSITORY sont requis.');
  }
  const github = new GitHub(GITHUB_TOKEN, GITHUB_REPOSITORY);
  if (mode === 'evenement') {
    await cleanEvent(github, JSON.parse(readFileSync(GITHUB_EVENT_PATH, 'utf8')));
  } else if (mode === 'arriere') {
    const budget = Number.parseInt(budgetArg ?? '300', 10);
    await cleanBacklog(github, Number.isFinite(budget) ? budget : 300, process.argv.includes('--avis'));
  } else {
    throw new Error(`mode inconnu : ${mode}`);
  }
  console.log(`${github.edits} texte(s) corrigé(s).`);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch((error) => {
    console.error(error);
    process.exitCode = 1;
  });
}
